import hashlib
import json
import re
import subprocess
from pathlib import Path

root = Path.cwd()
deliverables = root / 'deliverables'

def git_source(path):
    return subprocess.check_output(['git', 'show', f'HEAD:deliverables/{path}'])

def parse(blob):
    return [json.loads(line) for line in blob.splitlines() if line]

def scrub(value):
    if isinstance(value, str):
        value = value.replace(str(root) + '/', '').replace(str(root), '[workspace]')
        value = re.sub(r'/(?:home|Users|tmp|mnt|workspace)/[^\s)\]"`]+', '[path removed]', value)
        value = re.sub(r'(?<![\w.-])[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}', '[email removed]', value)
        return re.sub(r'(?<![\w-])(?:sk-[\w-]{20,}|(?:AKIA|ASIA)[A-Z0-9]{16}|gh[pousr]_[\w]{30,})',
                      '[credential removed]', value)
    if isinstance(value, dict):
        return {key: scrub(item) for key, item in value.items()}
    if isinstance(value, list):
        return [scrub(item) for item in value]
    return value

def filtered(row, source_line):
    payload = row['payload']
    kind = row['type']
    if kind == 'session_meta':
        selected = {key: payload[key] for key in ('session_id', 'timestamp') if key in payload}
    elif kind == 'turn_context':
        selected = {key: payload[key] for key in ('model', 'effort') if key in payload}
    else:
        selected = {key: payload[key] for key in ('type', 'role', 'phase') if key in payload}
        if payload.get('type') == 'message':
            selected['content'] = [{'type': part['type'], 'text': scrub(part['text'])}
                                   for part in payload['content'] if 'text' in part]
        elif payload.get('type') == 'verification_excerpt':
            selected['results'] = scrub(payload['results'])
        else:
            raise ValueError('Unapproved transcript record')
    return {'timestamp': row.get('timestamp'), 'source_line': source_line, 'type': kind, 'payload': selected}

def save(name, source, keep):
    selected = [filtered(row, number) for number, row in enumerate(source, 1) if keep(number, row)]
    blob = ''.join(json.dumps(row, ensure_ascii=False) + '\n' for row in selected).encode()
    (deliverables/name).write_bytes(blob)
    print(name, 'records', len(selected), 'user turn lines',
          [number for number, row in enumerate(selected, 1) if row['payload'].get('role') == 'user'])
    return hashlib.sha256(blob).hexdigest(), len(blob)

initial_user_lines = {12, 68, 131}
initial_assistant_lines = {16, 38, 61, 71, 89, 105, 124, 136, 154, 181, 192, 228, 255, 267,
                           289, 300, 313, 326, 339, 351, 370, 382, 426, 450, 462, 483, 499,
                           524, 546, 557, 571, 597, 614, 628}
initial = parse(git_source('session.jsonl'))
digest, size = save('session.jsonl', initial, lambda n, row:
    n in initial_user_lines | initial_assistant_lines or row['type'] in ('session_meta', 'turn_context'))
metadata = json.loads(git_source('session-capture.json'))
capture = {key: metadata[key] for key in ('session_id', 'agent', 'model', 'branch',
    'started_at', 'last_checkpoint_id', 'captured_through_commit') if key in metadata}
capture.update(snapshot_sha256=digest, snapshot_bytes=size,
               capture_setup='Entire',
               format='Filtered Codex transcript with original source line numbers')
(deliverables/'session-capture.json').write_text(json.dumps(capture, indent=2)+'\n')

assessment = parse(git_source('session-assessment.jsonl'))
save('session-assessment.jsonl', assessment, lambda n, row: n != 2)
current = json.loads(subprocess.check_output(['entire', 'session', 'current', '--json']))
if current.get('resolution') not in ('caller-env', 'ancestry'):
    raise ValueError('Entire did not resolve this agent session')
active = parse(subprocess.check_output(['entire', 'session', 'current', '--transcript']))
assert active[0]['payload']['session_id'] == current['session_id']

def keep_current(number, row):
    payload = row['payload']
    if row['type'] in ('session_meta', 'turn_context'):
        return True
    if row['type'] != 'response_item' or payload.get('type') != 'message':
        return False
    messages = [item.get('text', '') for item in payload.get('content', [])]
    return (payload.get('role') == 'user' and any(text.startswith((
            'review the code in this workspace', 'make the recommended fixes',
            "Help me improve this project's score", 'commit changes to git')) for text in messages)
            or payload.get('role') == 'assistant' and (payload.get('phase') == 'commentary'
            or any(text.startswith('**Yes. In live OpenAI mode') for text in messages)))

save('session-privacy.jsonl', active, keep_current)
